package com.example.gameworkbench.controller;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.example.gameworkbench.common.ApiResponse; import com.example.gameworkbench.dto.admin.UpdateUserAccessRequest; import com.example.gameworkbench.entity.UserRoleAudit; import com.example.gameworkbench.service.AdminUserService; import com.example.gameworkbench.vo.admin.AdminUserVO; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequiredArgsConstructor @RequestMapping("/api/admin/users") @PreAuthorize("@capabilityAuthorizationService.has(authentication, 'admin.users.manage')") public class AdminUserController { private final AdminUserService service; @GetMapping public ApiResponse<Page<AdminUserVO>> list(@AuthenticationPrincipal Long id,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String username,@RequestParam(required=false)String role,@RequestParam(required=false)String status){return ApiResponse.success(service.list(id,pageNum,pageSize,username,role,status));} @PatchMapping("/{targetId}") public ApiResponse<AdminUserVO> update(@AuthenticationPrincipal Long id,@PathVariable long targetId,@Valid @RequestBody UpdateUserAccessRequest r){return ApiResponse.success(service.update(id,targetId,r));} @GetMapping("/{targetId}/audits") public ApiResponse<List<UserRoleAudit>> audits(@PathVariable long targetId){return ApiResponse.success(service.audits(targetId));} }
